-- H2 projection of V2/V4 fields exposed by the revision service.
CREATE TABLE playlist(id BINARY(16) PRIMARY KEY,user_id BINARY(16) NOT NULL,name VARCHAR(100) NOT NULL,revision BIGINT NOT NULL DEFAULT 1,deleted_at TIMESTAMP(3),updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tag(id BINARY(16) PRIMARY KEY,user_id BINARY(16) NOT NULL,name VARCHAR(50) NOT NULL,revision BIGINT NOT NULL DEFAULT 1,archived_at TIMESTAMP(3),updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE song(id BINARY(16) PRIMARY KEY,user_id BINARY(16) NOT NULL,revision BIGINT DEFAULT 1,updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP,source_type VARCHAR(16),tj_number VARCHAR(20),title VARCHAR(200),artist VARCHAR(200),version_code VARCHAR(16),note VARCHAR(2000),representative_key_mode VARCHAR(16),representative_key_shift SMALLINT,song_tier CHAR(1),representative_recording_id BINARY(16),lifecycle_state VARCHAR(16),deleted_at TIMESTAMP(3));
CREATE TABLE recording(id BINARY(16) PRIMARY KEY,user_id BINARY(16) NOT NULL,revision BIGINT DEFAULT 1,updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP,song_id BINARY(16),title_snapshot VARCHAR(200),artist_snapshot VARCHAR(200),version_code VARCHAR(16),key_mode VARCHAR(16),key_shift SMALLINT,tier CHAR(1),note VARCHAR(2000),metadata_state VARCHAR(16),lifecycle_state VARCHAR(16),link_revision BIGINT DEFAULT 1,condition_code VARCHAR(16),condition_name_snapshot VARCHAR(50),deleted_at TIMESTAMP(3));
